"""Pinned MIT-licensed S24 Ultra vendor loader; hashes match Go's embedded assets.

Source: https://github.com/Ishabdullah/OpenCL-S24-Ultra
Kept in Python source so both pip and tools/dist wheels include the assets.
"""
from __future__ import annotations

PATCH = "diff --git a/ggml/src/ggml-opencl/CMakeLists.txt b/ggml/src/ggml-opencl/CMakeLists.txt\nindex 97b862a..759f268 100644\n--- a/ggml/src/ggml-opencl/CMakeLists.txt\n+++ b/ggml/src/ggml-opencl/CMakeLists.txt\n@@ -1,4 +1,10 @@\n-find_package(OpenCL REQUIRED)\n+option(GGML_OPENCL_USE_SPHAL \"Load Qualcomm OpenCL through the Android sphal namespace\" OFF)\n+\n+if (GGML_OPENCL_USE_SPHAL)\n+    find_path(OpenCL_INCLUDE_DIRS NAMES CL/cl.h REQUIRED)\n+else ()\n+    find_package(OpenCL REQUIRED)\n+endif ()\n find_package(Python3 REQUIRED)\n \n set(TARGET_NAME ggml-opencl)\n@@ -8,7 +14,13 @@ ggml_add_backend_library(${TARGET_NAME}\n                          cl-program-cache.cpp\n                          cl-program-cache.h\n                          ../../include/ggml-opencl.h)\n-target_link_libraries(${TARGET_NAME} PRIVATE ${OpenCL_LIBRARIES})\n+if (GGML_OPENCL_USE_SPHAL)\n+    target_sources(${TARGET_NAME} PRIVATE opencl-sphal.cpp opencl-sphal.h)\n+    target_compile_definitions(${TARGET_NAME} PRIVATE GGML_OPENCL_USE_SPHAL)\n+    target_link_libraries(${TARGET_NAME} PRIVATE ${CMAKE_DL_LIBS})\n+else ()\n+    target_link_libraries(${TARGET_NAME} PRIVATE ${OpenCL_LIBRARIES})\n+endif ()\n target_include_directories(${TARGET_NAME} PRIVATE ${OpenCL_INCLUDE_DIRS})\n \n if (GGML_OPENCL_PROFILING)\ndiff --git a/ggml/src/ggml-opencl/cl-program-cache.cpp b/ggml/src/ggml-opencl/cl-program-cache.cpp\nindex 1a4a281..3f67867 100644\n--- a/ggml/src/ggml-opencl/cl-program-cache.cpp\n+++ b/ggml/src/ggml-opencl/cl-program-cache.cpp\n@@ -4,6 +4,9 @@\n #define CL_USE_DEPRECATED_OPENCL_1_2_APIS\n \n #include \"cl-program-cache.h\"\n+#ifdef GGML_OPENCL_USE_SPHAL\n+#include \"opencl-sphal.h\"\n+#endif\n \n #include \"ggml-impl.h\"  // GGML_LOG_INFO / WARN\n \ndiff --git a/ggml/src/ggml-opencl/ggml-opencl.cpp b/ggml/src/ggml-opencl/ggml-opencl.cpp\nindex acad7a6..ea54789 100644\n--- a/ggml/src/ggml-opencl/ggml-opencl.cpp\n+++ b/ggml/src/ggml-opencl/ggml-opencl.cpp\n@@ -32,6 +32,9 @@ typedef const void * (*get_adreno_bin_kernel_func_t)(\n );\n \n #include <CL/cl.h>\n+#ifdef GGML_OPENCL_USE_SPHAL\n+#include \"opencl-sphal.h\"\n+#endif\n \n #include <inttypes.h>\n #include <string.h>\n@@ -6306,9 +6309,16 @@ static std::vector<ggml_backend_device> ggml_opencl_probe_devices(ggml_backend_r\n     struct cl_device * default_device = NULL;\n     unsigned           default_platform_number = 0;\n \n+#ifdef GGML_OPENCL_USE_SPHAL\n+    if (!ggml_opencl_sphal_init()) {\n+        return found_devices;\n+    }\n+#endif\n+\n     cl_platform_id platform_ids[NPLAT];\n-    if (clGetPlatformIDs(NPLAT, platform_ids, &n_platforms) != CL_SUCCESS) {\n-        GGML_LOG_ERROR(\"ggml_opencl: platform IDs not available.\\n\");\n+    cl_int platform_err = clGetPlatformIDs(NPLAT, platform_ids, &n_platforms);\n+    if (platform_err != CL_SUCCESS) {\n+        GGML_LOG_ERROR(\"ggml_opencl: clGetPlatformIDs failed: %d, platforms: %u\\n\", platform_err, n_platforms);\n         return found_devices;\n     }\n \ndiff --git a/ggml/src/ggml-opencl/opencl-sphal.cpp b/ggml/src/ggml-opencl/opencl-sphal.cpp\nnew file mode 100644\nindex 0000000..a3dc94e\n--- /dev/null\n+++ b/ggml/src/ggml-opencl/opencl-sphal.cpp\n@@ -0,0 +1,81 @@\n+#define CL_TARGET_OPENCL_VERSION GGML_OPENCL_TARGET_VERSION\n+#define CL_USE_DEPRECATED_OPENCL_1_2_APIS\n+#define GGML_OPENCL_SPHAL_NO_REMAP\n+\n+#include \"opencl-sphal.h\"\n+#include \"ggml-impl.h\"\n+\n+#include <android/dlext.h>\n+#include <dlfcn.h>\n+#include <mutex>\n+\n+ggml_opencl_sphal_dispatch ggml_opencl_sphal = {};\n+\n+static bool ggml_opencl_sphal_load() {\n+    using get_namespace_fn = android_namespace_t * (*)(const char *);\n+    using dlopen_ext_fn = void * (*)(const char *, int, const android_dlextinfo *);\n+\n+    auto get_ns = reinterpret_cast<get_namespace_fn>(dlsym(RTLD_DEFAULT, \"__loader_android_get_exported_namespace\"));\n+    auto open_ext = reinterpret_cast<dlopen_ext_fn>(dlsym(RTLD_DEFAULT, \"android_dlopen_ext\"));\n+    if (!get_ns || !open_ext) {\n+        GGML_LOG_ERROR(\"ggml_opencl: Android namespace API unavailable\\n\");\n+        return false;\n+    }\n+\n+    android_namespace_t * sphal = get_ns(\"sphal\");\n+    if (!sphal) {\n+        GGML_LOG_ERROR(\"ggml_opencl: Android sphal namespace unavailable\\n\");\n+        return false;\n+    }\n+\n+    android_dlextinfo ext = {};\n+    ext.flags = ANDROID_DLEXT_USE_NAMESPACE;\n+    ext.library_namespace = sphal;\n+\n+    // Keep both handles for process lifetime; dispatch pointers depend on them.\n+    void * driver = open_ext(\"/vendor/lib64/libOpenCL_adreno.so\", RTLD_NOW | RTLD_LOCAL, &ext);\n+    if (!driver) {\n+        GGML_LOG_ERROR(\"ggml_opencl: Adreno driver load failed: %s\\n\", dlerror());\n+        return false;\n+    }\n+\n+    using init_driver_fn = int (*)(void);\n+    auto init_driver = reinterpret_cast<init_driver_fn>(dlsym(driver, \"InitOpenCLDriver\"));\n+    if (!init_driver) {\n+        GGML_LOG_ERROR(\"ggml_opencl: InitOpenCLDriver unavailable: %s\\n\", dlerror());\n+        return false;\n+    }\n+\n+    // Qualcomm initialization must precede loading its OpenCL ICD.\n+    const int rc = init_driver();\n+    GGML_LOG_INFO(\"ggml_opencl: sphal InitOpenCLDriver() = %d\\n\", rc);\n+    if (rc != 0) {\n+        GGML_LOG_ERROR(\"ggml_opencl: Adreno initialization failed: %d\\n\", rc);\n+        return false;\n+    }\n+\n+    void * loader = open_ext(\"/vendor/lib64/libOpenCL.so\", RTLD_NOW | RTLD_LOCAL, &ext);\n+    if (!loader) {\n+        GGML_LOG_ERROR(\"ggml_opencl: Qualcomm OpenCL loader failed: %s\\n\", dlerror());\n+        return false;\n+    }\n+\n+    ggml_opencl_sphal_dispatch dispatch = {};\n+#define GGML_OPENCL_SPHAL_RESOLVE(name) \\\n+    dispatch.name = reinterpret_cast<decltype(dispatch.name)>(dlsym(loader, #name)); \\\n+    if (!dispatch.name) { \\\n+        GGML_LOG_ERROR(\"ggml_opencl: Qualcomm OpenCL symbol %s unavailable: %s\\n\", #name, dlerror()); \\\n+        return false; \\\n+    }\n+    GGML_OPENCL_SPHAL_FUNCTIONS(GGML_OPENCL_SPHAL_RESOLVE)\n+#undef GGML_OPENCL_SPHAL_RESOLVE\n+    ggml_opencl_sphal = dispatch;\n+    return true;\n+}\n+\n+bool ggml_opencl_sphal_init() {\n+    static std::once_flag once;\n+    static bool ready = false;\n+    std::call_once(once, [] { ready = ggml_opencl_sphal_load(); });\n+    return ready;\n+}\ndiff --git a/ggml/src/ggml-opencl/opencl-sphal.h b/ggml/src/ggml-opencl/opencl-sphal.h\nnew file mode 100644\nindex 0000000..9e82e7f\n--- /dev/null\n+++ b/ggml/src/ggml-opencl/opencl-sphal.h\n@@ -0,0 +1,91 @@\n+#pragma once\n+\n+#include <CL/cl.h>\n+\n+#define GGML_OPENCL_SPHAL_FUNCTIONS(X) \\\n+    X(clBuildProgram) \\\n+    X(clCreateBuffer) \\\n+    X(clCreateBufferWithProperties) \\\n+    X(clCreateCommandQueue) \\\n+    X(clCreateContext) \\\n+    X(clCreateImage) \\\n+    X(clCreateKernel) \\\n+    X(clCreateProgramWithBinary) \\\n+    X(clCreateProgramWithSource) \\\n+    X(clCreateSubBuffer) \\\n+    X(clEnqueueBarrierWithWaitList) \\\n+    X(clEnqueueCopyBuffer) \\\n+    X(clEnqueueFillBuffer) \\\n+    X(clEnqueueMapBuffer) \\\n+    X(clEnqueueMarkerWithWaitList) \\\n+    X(clEnqueueNDRangeKernel) \\\n+    X(clEnqueueReadBuffer) \\\n+    X(clEnqueueUnmapMemObject) \\\n+    X(clEnqueueWriteBuffer) \\\n+    X(clFinish) \\\n+    X(clFlush) \\\n+    X(clGetDeviceIDs) \\\n+    X(clGetDeviceInfo) \\\n+    X(clGetEventProfilingInfo) \\\n+    X(clGetKernelInfo) \\\n+    X(clGetKernelSubGroupInfo) \\\n+    X(clGetKernelWorkGroupInfo) \\\n+    X(clGetPlatformIDs) \\\n+    X(clGetPlatformInfo) \\\n+    X(clGetProgramBuildInfo) \\\n+    X(clGetProgramInfo) \\\n+    X(clReleaseEvent) \\\n+    X(clReleaseKernel) \\\n+    X(clReleaseMemObject) \\\n+    X(clReleaseProgram) \\\n+    X(clSetKernelArg) \\\n+    X(clWaitForEvents)\n+\n+struct ggml_opencl_sphal_dispatch {\n+#define GGML_OPENCL_SPHAL_FIELD(name) decltype(&::name) name;\n+    GGML_OPENCL_SPHAL_FUNCTIONS(GGML_OPENCL_SPHAL_FIELD)\n+#undef GGML_OPENCL_SPHAL_FIELD\n+};\n+\n+extern ggml_opencl_sphal_dispatch ggml_opencl_sphal;\n+bool ggml_opencl_sphal_init();\n+\n+#ifndef GGML_OPENCL_SPHAL_NO_REMAP\n+#define clBuildProgram ggml_opencl_sphal.clBuildProgram\n+#define clCreateBuffer ggml_opencl_sphal.clCreateBuffer\n+#define clCreateBufferWithProperties ggml_opencl_sphal.clCreateBufferWithProperties\n+#define clCreateCommandQueue ggml_opencl_sphal.clCreateCommandQueue\n+#define clCreateContext ggml_opencl_sphal.clCreateContext\n+#define clCreateImage ggml_opencl_sphal.clCreateImage\n+#define clCreateKernel ggml_opencl_sphal.clCreateKernel\n+#define clCreateProgramWithBinary ggml_opencl_sphal.clCreateProgramWithBinary\n+#define clCreateProgramWithSource ggml_opencl_sphal.clCreateProgramWithSource\n+#define clCreateSubBuffer ggml_opencl_sphal.clCreateSubBuffer\n+#define clEnqueueBarrierWithWaitList ggml_opencl_sphal.clEnqueueBarrierWithWaitList\n+#define clEnqueueCopyBuffer ggml_opencl_sphal.clEnqueueCopyBuffer\n+#define clEnqueueFillBuffer ggml_opencl_sphal.clEnqueueFillBuffer\n+#define clEnqueueMapBuffer ggml_opencl_sphal.clEnqueueMapBuffer\n+#define clEnqueueMarkerWithWaitList ggml_opencl_sphal.clEnqueueMarkerWithWaitList\n+#define clEnqueueNDRangeKernel ggml_opencl_sphal.clEnqueueNDRangeKernel\n+#define clEnqueueReadBuffer ggml_opencl_sphal.clEnqueueReadBuffer\n+#define clEnqueueUnmapMemObject ggml_opencl_sphal.clEnqueueUnmapMemObject\n+#define clEnqueueWriteBuffer ggml_opencl_sphal.clEnqueueWriteBuffer\n+#define clFinish ggml_opencl_sphal.clFinish\n+#define clFlush ggml_opencl_sphal.clFlush\n+#define clGetDeviceIDs ggml_opencl_sphal.clGetDeviceIDs\n+#define clGetDeviceInfo ggml_opencl_sphal.clGetDeviceInfo\n+#define clGetEventProfilingInfo ggml_opencl_sphal.clGetEventProfilingInfo\n+#define clGetKernelInfo ggml_opencl_sphal.clGetKernelInfo\n+#define clGetKernelSubGroupInfo ggml_opencl_sphal.clGetKernelSubGroupInfo\n+#define clGetKernelWorkGroupInfo ggml_opencl_sphal.clGetKernelWorkGroupInfo\n+#define clGetPlatformIDs ggml_opencl_sphal.clGetPlatformIDs\n+#define clGetPlatformInfo ggml_opencl_sphal.clGetPlatformInfo\n+#define clGetProgramBuildInfo ggml_opencl_sphal.clGetProgramBuildInfo\n+#define clGetProgramInfo ggml_opencl_sphal.clGetProgramInfo\n+#define clReleaseEvent ggml_opencl_sphal.clReleaseEvent\n+#define clReleaseKernel ggml_opencl_sphal.clReleaseKernel\n+#define clReleaseMemObject ggml_opencl_sphal.clReleaseMemObject\n+#define clReleaseProgram ggml_opencl_sphal.clReleaseProgram\n+#define clSetKernelArg ggml_opencl_sphal.clSetKernelArg\n+#define clWaitForEvents ggml_opencl_sphal.clWaitForEvents\n+#endif\n"
